before.content:
        hostHandshake.readMessage(clientHandshake.writeMessage());
        clientHandshake.readMessage(hostHandshake.writeMessage());
        hostHandshake.readMessage(clientHandshake.writeMessage());
        try (var client = clientHandshake.finish(hostKey.publicKey(), route)) {
            client.setTransportState(1L << 20, 0, -1L, 0);
            assertThrows(IllegalStateException.class,
                    () -> client.encrypt("epoch-exhausted".getBytes(StandardCharsets.UTF_8)));
            assertThrows(IllegalStateException.class,
                    () -> client.encrypt("closed".getBytes(StandardCharsets.UTF_8)));
        }
    }
}

after.content:
        hostHandshake.readMessage(clientHandshake.writeMessage());
        clientHandshake.readMessage(hostHandshake.writeMessage());
        hostHandshake.readMessage(clientHandshake.writeMessage());
        try (var client = clientHandshake.finish(hostKey.publicKey(), route);
             var host = hostHandshake.finish(clientKey.publicKey(), route)) {
            client.setTransportState(1L << 20, 0, -1L, 0);
            assertThrows(IllegalStateException.class,
                    () -> client.encrypt("epoch-exhausted".getBytes(StandardCharsets.UTF_8)));
            assertThrows(IllegalStateException.class,
                    () -> client.encrypt("closed".getBytes(StandardCharsets.UTF_8)));

            host.setTransportState(0, 1L << 20, 0, -1L);
            assertThrows(IllegalStateException.class, () -> host.decrypt(
                    new NoiseTransport.Frame(1L << 20, 0, new byte[16])));
            assertThrows(IllegalStateException.class, () -> host.decrypt(
                    new NoiseTransport.Frame(1L << 20, 0, new byte[16])));
        }
    }
}
